              <TableHead className="text-right">Value used</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {derivation.operands.map((operand, index) => (
              <TableRow key={index}>
                <TableCell>{operand.row_label}</TableCell>
